// HasJob applies the HasEdge predicate on the "job" edge.
func HasJob() predicate.DiscoveryResult {
	return predicate.DiscoveryResult(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, JobTable, JobColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasJobWith applies the HasEdge predicate on the "job" edge with a given conditions (other predicates).
func HasJobWith(preds ...predicate.DiscoveryJob) predicate.DiscoveryResult {
	return predicate.DiscoveryResult(func(s *sql.Selector) {
		step := newJobStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.DiscoveryResult) predicate.DiscoveryResult {
	return predicate.DiscoveryResult(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.DiscoveryResult) predicate.DiscoveryResult {
	return predicate.DiscoveryResult(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.DiscoveryResult) predicate.DiscoveryResult {
	return predicate.DiscoveryResult(sql.NotPredicates(p))
}
